export const getAskPdfUrl = () => {
  return `/api/gemini/pdf/ask`;
};

export const askPdf = async (
  pdfAskInput: PdfAskInput,
  options?: RequestInit,
): Promise<PdfAskOutput> => {
  return customFetch<PdfAskOutput>(getAskPdfUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(pdfAskInput),
  });
};

export const getAskPdfMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof askPdf>>,
    TError,
    { data: BodyType<PdfAskInput> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof askPdf>>,
  TError,
  { data: BodyType<PdfAskInput> },
  TContext
> => {
  const mutationKey = ["askPdf"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof askPdf>>,
    { data: BodyType<PdfAskInput> }
  > = (props) => {
    const { data } = props ?? {};

    return askPdf(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type AskPdfMutationResult = NonNullable<
  Awaited<ReturnType<typeof askPdf>>
>;
export type AskPdfMutationBody = BodyType<PdfAskInput>;
export type AskPdfMutationError = ErrorType<unknown>;

/**
 * @summary Ask a question about PDF text content
 */
export const useAskPdf = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof askPdf>>,
    TError,
    { data: BodyType<PdfAskInput> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof askPdf>>,
  TError,
  { data: BodyType<PdfAskInput> },
  TContext
> => {
  return useMutation(getAskPdfMutationOptions(options));
};
